59	// fragDataEnv wraps one fragment in a mux message and a reliable
60	// envelope with explicit sequences.
61	func fragDataEnv(relSeq, muxSeq uint32, ch uint16, msg, idx, total uint32, fl uint8, ack uint32, chunk []byte) envelope {
62		return muxMsg(relSeq, ch, muxSeq, 0, 0, encodeFragHeader(msg, idx, total, fl, ack, chunk))
63	}
64	
65	// fragWire is one parsed fragment off the wire.
66	type fragWire struct {
67		ch     uint16
68		muxSeq uint32
69		msg    uint32
70		idx    uint32
71		total  uint32
72		flags  uint8
73		chunk  []byte
74	}
75	
76	// parseFragWire decodes flushed sender bytes into fragments, skipping
77	// mux FIN frames and frag-level standalone acks.
78	func parseFragWire(t *testing.T, wire []byte, baseSeq uint32) []fragWire {
79		t.Helper()
80		var out []fragWire
81		for _, w := range parseMuxWire(t, wire, baseSeq) {
82			if w.flags&mhFlagFin != 0 {
83				continue
84			}
85			msg, idx, total, fl, _, chunk, err := decodeFragHeader(w.payload)
86			if err != nil {
87				t.Fatalf("decodeFragHeader: %v", err)
88			}
89			if fl&fhFlagAck != 0 {
90				continue
91			}
92			out = append(out, fragWire{ch: w.ch, muxSeq: w.seq, msg: msg, idx: idx, total: total, flags: fl, chunk: chunk})
93		}
94		return out
95	}
