122	func TestFragHeaderLayout(t *testing.T) {
123		if FragHeaderSize != 21 {
124			t.Fatalf("FragHeaderSize = %d, want 21", FragHeaderSize)
125		}
126		if FragMaxPayload != MuxMaxPayload-21 {
127			t.Fatalf("FragMaxPayload = %d, want %d", FragMaxPayload, MuxMaxPayload-21)
128		}
129		b := encodeFragHeader(0x01020304, 0x05060708, 0x090A0B0C, 0x01, 0x0D0E0F10, []byte("xy"))
130		want := []byte{0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08,
131			0x09, 0x0A, 0x0B, 0x0C, 0x01, 0x0D, 0x0E, 0x0F, 0x10}
132		if !bytes.Equal(b[:17], want) {
133			t.Fatalf("header prefix = % x, want % x", b[:17], want)
134		}
135		if !bytes.Equal(b[21:], []byte("xy")) {
136			t.Fatalf("chunk = %x", b[21:])
137		}
138		msg, idx, total, fl, ack, chunk, err := decodeFragHeader(b)
139		if err != nil {
140			t.Fatalf("decodeFragHeader: %v", err)
141		}
142		if msg != 0x01020304 || idx != 0x05060708 || total != 0x090A0B0C ||
143			fl != 0x01 || ack != 0x0D0E0F10 || !bytes.Equal(chunk, []byte("xy")) {
144			t.Fatalf("round trip = %x %x %x %x %x %q", msg, idx, total, fl, ack, chunk)
145		}
146		b[3] ^= 0x80
147		if _, _, _, _, _, _, err := decodeFragHeader(b); !errors.Is(err, ErrChecksum) {
148			t.Fatalf("flipped header err = %v, want ErrChecksum", err)
149		}
150		if _, _, _, _, _, _, err := decodeFragHeader(b[:10]); !errors.Is(err, ErrChecksum) {
151			t.Fatalf("short header err = %v, want ErrChecksum", err)
152		}
153	}
