994	func TestFragCloseChannelSemantics(t *testing.T) {
995		cfg := muxCfg(t, 3, 8)
996		var wire bytes.Buffer
997		snd := newFragSender(t, &wire, cfg, 1<<20)
998	
999		if err := snd.WriteFrame(FragFrame{Channel: 0, Kind: 3, Payload: []byte("data")}); err != nil {
1000			t.Fatal(err)
1001		}
1002		if err := snd.CloseChannel(0); err != nil {
1003			t.Fatal(err)
1004		}
1005		if err := snd.CloseChannel(1); err != nil { // empty channel
1006			t.Fatal(err)
1007		}
1008		// Refusals compare equal to the established values directly.
1009		if err := snd.CloseChannel(0); err != ErrChannelClosed {
1010			t.Fatalf("second close err = %v, want ErrChannelClosed", err)
1011		}
1012		if err := snd.WriteFrame(FragFrame{Channel: 0, Payload: []byte("z")}); err != ErrChannelClosed {
1013			t.Fatalf("write on closed err = %v, want ErrChannelClosed", err)
1014		}
1015		if err := snd.CloseChannel(9); err != ErrChecksum {
1016			t.Fatalf("out-of-range close err = %v, want ErrChecksum", err)
1017		}
1018		if err := snd.Flush(); err != nil {
1019			t.Fatal(err)
1020		}
1021	
1022		f := newFeed()
1023		rcv := newFragReceiver(t, f, cfg, 1<<20)
1024		f.replace(wire.Bytes())
1025		got, err := rcv.ReadFrame()
1026		if err != nil || string(got.Payload) != "data" {
1027			t.Fatalf("data = %+v, %v", got, err)
1028		}
1029		eofs := map[uint16]bool{}
1030		for len(eofs) < 2 {
1031			cf, err := rcv.ReadFrame()
1032			if !errors.Is(err, io.EOF) {
1033				t.Fatalf("err = %v, want io.EOF", err)
1034			}
1035			eofs[cf.Channel] = true
1036		}
1037		if !eofs[0] || !eofs[1] {
1038			t.Fatalf("eofs = %v, want channels 0 and 1", eofs)
1039		}
1040	
1041		// Concurrent closes of one channel do not panic; exactly one wins
1042		// and the rest get the established closed value.
1043		const n = 6
1044		errs := make([]error, n)
1045		var wg sync.WaitGroup
1046		for i := 0; i < n; i++ {
1047			wg.Add(1)
1048			go func(i int) {
1049				defer wg.Done()
1050				errs[i] = snd.CloseChannel(2)
1051			}(i)
1052		}
1053		wg.Wait()
1054		ok := 0
1055		for _, err := range errs {
1056			if err == nil {
1057				ok++
1058				continue
1059			}
1060			if err != ErrChannelClosed {
1061				t.Fatalf("concurrent close err = %v, want ErrChannelClosed", err)
1062			}
1063		}
1064		if ok != 1 {
1065			t.Fatalf("%d closes succeeded, want exactly 1", ok)
1066		}
1067	
1068		// After Close, a repeated close still returns the established value
1069		// without hanging on the stopped pump.
1070		snd.Close()
1071		if err := snd.CloseChannel(2); err != ErrChannelClosed {
1072			t.Fatalf("close after Close err = %v, want ErrChannelClosed", err)
1073		}
1074	}
