	n := 1
	if len(f.Payload) > 0 {
		n = (len(f.Payload) + FragMaxPayload - 1) / FragMaxPayload
	}
	if n > fs.window {
		// A message wider than the window can never enter the quota even
		// with it relaxed to the ceiling: reject it before it waits.
		return ErrTooLarge
	}

	fs.mu.Lock()
	defer fs.mu.Unlock()

