		fl.sleeping--
	}

	msg := fs.sendNext[ch]
	total := uint32(len(f.Payload))
	frames := make([]ChannelFrame, 0, n)
	for i := 0; i < n; i++ {
		lo := i * FragMaxPayload
		hi := lo + FragMaxPayload
