// refreshFlowLocked reconciles one channel's in-flight accounting with
// the mux send positions: confirmed fragments leave the in-flight set,
// timely acknowledgement relaxes the quota up to the window, and a
// freed mux window clears a control-frame full mark. It then wakes the
// head waiter so suspended writes recheck. Caller holds mu.
func (fs *FragSession) refreshFlowLocked(ch uint16) {
    fl := &fs.flow[ch]
    next, acked, _ := fs.mux.sendState(ch)
    k := 0
    for k < len(fl.seqs) && fl.seqs[k] < acked {
        k++
    }
    if k > 0 {
        fl.seqs = append(fl.seqs[:0], fl.seqs[k:]...)  // hmm aliasing: append(fl.seqs[:0], ...) reuses array — fine since we then reslice
        fl.seqs = fl.seqs[:len(fl.seqs)-k]  // wait, append already reslices
        fl.confirmed += uint64(k)
        // Timely acknowledgement relaxes the quota, one fragment per
        // confirmed fragment, up to the window ceiling.
        fl.quota += k
        if fl.quota > fs.window {
            fl.quota = fs.window
        }
    }
    if fl.muxFull && next-acked < uint32(fs.window) {
        fl.muxFull = false
    }
    fs.wakeHeadLocked(ch)
}
```

